 EXECUTE format('CREATE TABLE IF NOT EXISTS growth_leads(id UUID PRIMARY KEY,tenant_id %s NOT NULL REFERENCES tenants(id),pipeline TEXT NOT NULL CHECK(pipeline IN (''tenant'',''client'')),name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 150),email TEXT NOT NULL DEFAULT '''',phone TEXT NOT NULL DEFAULT '''',source TEXT NOT NULL,reference TEXT NOT NULL CHECK(length(reference) BETWEEN 1 AND 500),contact_basis TEXT NOT NULL CHECK(contact_basis IN (''requested'',''business_prospect'',''not_requested'')),contact_hash TEXT NOT NULL,stage TEXT NOT NULL DEFAULT ''new'',campaign_id UUID,owner_id %s REFERENCES users(id),due_at TIMESTAMPTZ,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,pipeline,contact_hash),FOREIGN KEY(tenant_id,campaign_id) REFERENCES growth_campaigns(tenant_id,id))',tenant_type,actor_type);
 EXECUTE format('CREATE TABLE IF NOT EXISTS growth_milestones(tenant_id %s NOT NULL,lead_id UUID NOT NULL,stage TEXT NOT NULL,evidence TEXT NOT NULL DEFAULT '''',recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(tenant_id,lead_id,stage),FOREIGN KEY(tenant_id,lead_id) REFERENCES growth_leads(tenant_id,id))',tenant_type);
 EXECUTE format('CREATE TABLE IF NOT EXISTS growth_tasks(id UUID PRIMARY KEY,tenant_id %s NOT NULL REFERENCES tenants(id),name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 200),owner_id %s NOT NULL REFERENCES users(id),due_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL DEFAULT ''open'' CHECK(status IN (''open'',''done'')),evidence TEXT NOT NULL DEFAULT '''',version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(status<>''done'' OR length(evidence)>0))',tenant_type,actor_type);
 EXECUTE format('CREATE TABLE IF NOT EXISTS growth_audit(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor_id %s NOT NULL REFERENCES users(id),tenant_id %s NOT NULL REFERENCES tenants(id),action TEXT NOT NULL,target_id TEXT NOT NULL,evidence TEXT NOT NULL DEFAULT '''',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())',actor_type,tenant_type);
