CREATE TABLE IF NOT EXISTS growth_requests(actor_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,response JSONB NOT NULL,status INTEGER NOT NULL CHECK(status IN (200,201)),PRIMARY KEY(actor_id,idempotency_key));
CREATE TABLE IF NOT EXISTS growth_rate(actor_id TEXT PRIMARY KEY,attempts INTEGER NOT NULL,window_start TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS growth_leads_tenant_time ON growth_leads(tenant_id,created_at,id);
CREATE INDEX IF NOT EXISTS growth_tasks_tenant_due ON growth_tasks(tenant_id,status,due_at);
